LEN = struct.Struct(">I")
MAX_FRAME = 8 * 1024 * 1024


async def send_frame(writer: asyncio.StreamWriter, obj) -> None:
    payload = json.dumps(obj, separators=(",", ":")).encode()
    writer.write(LEN.pack(len(payload)) + payload)
