### Common framing: `frame.py`

Length-prefixed JSON messages so you don't deal with TCP partial reads:

```python
# frame.py
import json
import struct
import socket

HEADER = struct.Struct("!I")  # 4-byte big-endian length

def send_msg(sock: socket.socket, obj: dict):
    data = json.dumps(obj).encode("utf-8")
    sock.sendall(HEADER.pack(len(data)) + data)

def recv_exact(sock: socket.socket, n: int) -> bytes:
    buf = b""
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))
        if not chunk:
            raise ConnectionError("peer closed")
        buf += chunk
    return buf

def recv_msg(sock: socket.socket) -> dict:
    hdr = recv_exact(sock, HEADER.size)
    (length,) = HEADER.unpack(hdr)
    if length > 10 * 1024 * 1024:
        raise ValueError("frame too large")
    payload = recv_exact(sock, length)
    return json.loads(payload.decode("utf-8"))
