# tcp_frame.py — length-prefixed JSON/binary framing (contract: send_frame / recv_frame)
import json, struct, socket

HEADER = struct.Struct(">I")  # 4-byte big-endian length prefix

def send_frame(sock: socket.socket, payload: bytes, *, json_obj=None) -> None:
    if json_obj is not None:
        payload = json.dumps(json_obj).encode()
    sock.sendall(HEADER.pack(len(payload)) + payload)

def recv_exact(sock: socket.socket, n: int) -> bytes:
    buf = bytearray()
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))
        if not chunk:
            raise ConnectionError("peer closed")
        buf += chunk
    return bytes(buf)

def recv_frame(sock: socket.socket, max_size: int = 1 << 20) -> bytes:
    (length,) = HEADER.unpack(recv_exact(sock, HEADER.size))
    if length > max_size:
        raise ValueError(f"frame too large: {length}")
    return recv_exact(sock, length)

def recv_json(sock: socket.socket, max_size: int = 1 << 20):
    return json.loads(recv_frame(sock, max_size))
