### Common protocol

Length-prefixed frames: `4-byte big-endian length + payload bytes`. Payload can be anything — this layer just sends/receives `bytes`.

```python
# transport.py
import struct

HEADER_LEN = 4

def encode_frame(payload: bytes) -> bytes:
    return struct.pack("!I", len(payload)) + payload

def decode_frames(buffer: bytearray):
    """Yield complete payloads from buffer, keep remainder."""
    messages = []
    while len(buffer) >= HEADER_LEN:
        (msg_len,) = struct.unpack("!I", buffer[:HEADER_LEN])
        if len(buffer) < HEADER_LEN + msg_len:
            break
        messages.append(bytes(buffer[HEADER_LEN:HEADER_LEN+msg_len]))
        del buffer[:HEADER_LEN+msg_len]
    return messages
