### Server (`server.py`)

```python
import socket
import threading
import uuid

class TrackingTCPServer:
    def __init__(self, host='127.0.0.1', port=9000):
        self.host = host
        self.port = port
        self.clients = {}  # {client_id: socket}
        self.lock = threading.Lock()
        self.running = False

    def start(self):
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.sock.bind((self.host, self.port))
        self.sock.listen(5)
        self.running = True
        print(f"[*] Server listening on {self.host}:{self.port}")

        try:
            while self.running:
                conn, addr = self.sock.accept()
                client_id = str(uuid.uuid4())[:8]
                with self.lock:
                    self.clients[client_id] = conn
                print(f"[+] Client connected: {client_id} from {addr}")

                t = threading.Thread(target=self._handle_client, args=(client_id, conn), daemon=True)
                t.start()
        except KeyboardInterrupt:
            self.stop()

    def _handle_client(self, client_id, conn):
        try:
            while True:
                data = conn.recv(1024)
                if not data:
                    break
                print(f"[{client_id}] Received: {data.decode(errors='ignore')}")
                conn.sendall(b"ACK\n")
        except (ConnectionResetError, BrokenPipeError):
            pass
        finally:
            with self.lock:
                if client_id in self.clients:
                    del self.clients[client_id]
            conn.close()
            print(f"[-] Client disconnected: {client_id}")

    def stop(self):
        self.running = False
        with self.lock:
            for conn in self.clients.values():
                conn.close()
            self.clients.clear()
        if hasattr(self, 'sock'):
            self.sock.close()
        print("[*] Server stopped.")

if __name__ == "__main__":
    server = TrackingTCPServer()
    server.start()
