import socket
import time

class ReconnectingTCPClient:
    def __init__(self, host='127.0.0.1', port=9000, retry_interval=3):
        self.host = host
        self.port = port
        self.retry_interval = retry_interval
        self.sock = None
        self.running = False

    def connect(self):
        while self.running:
            try:
                print(f"[*] Attempting connection to {self.host}:{self.port}...")
                self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                self.sock.connect((self.host, self.port))
                print("[+] Connected to server.")
                return True
            except (ConnectionRefusedError, socket.timeout, OSError) as e:
                print(f"[-] Connection failed ({e}). Retrying in {self.retry_interval}s...")
                if self.sock:
                    self.sock.close()
                time.sleep(self.retry_interval)
        return False

    def run(self):
        self.running = True
        while self.running:
            if not self.connect():
                break

            # Communication loop
            try:
                while self.running:
                    self.sock.sendall(b"ping")
                    data = self.sock.recv(1024)
                    if not data:
                        raise ConnectionResetError("Server closed connection")
                    print(f"[*] Server response: {data.decode(errors='ignore').strip()}")
                    time.sleep(2)
            except (ConnectionResetError, BrokenPipeError, OSError):
                print("[-] Connection lost. Resetting...")
                if self.sock:
                    self.sock.close()
